import sys
from datetime import date, timedelta


def parse(text):
    y, m, d = map(int, text.split("-"))
    return date(y, m, d)


def is_holiday(day, holidays):
    return day in holidays


def is_workday(day):
    return day.weekday() < 5


def main():
    holidays = set()
    allowance = {}
    used = {}
    for line in sys.stdin:
        parts = line.strip().split()
        if not parts:
            continue
        if parts[0] == "holiday":
            holidays.add(parse(parts[1]))
        elif parts[0] == "allowance":
            allowance[parts[1]] = int(parts[2])
        elif parts[0] == "leave":
            first, last = parse(parts[2]), parse(parts[3])
            if first > last:
                continue
            count = 0
            current = first
            while current <= last:
                if is_holiday(current, holidays) or not is_workday(current):
                    current += timedelta(days=1)
                    continue
                count += 1
                current += timedelta(days=1)
            used[parts[1]] = used.get(parts[1], 0) + count
    for name in sorted(used):
        u = used[name]
        l = allowance.get(name, 0)
        if u <= l:
            print(f"{name} used {u} left {l - u}")
        else:
            print(f"{name} used {u} over {u - l}")


if __name__ == "__main__":
    main()
